import { useEffect } from 'react';

export function useAnimations() {
  useEffect(() => {
    // Scroll Observer
    const observerOptions = {
      root: null,
      rootMargin: '0px',
      threshold: 0.15
    };

    const observer = new IntersectionObserver((entries, observer) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('visible');
          
          // Counter animation if it's a number
          if (entry.target.classList.contains('animated-counter')) {
            const target = parseInt(entry.target.getAttribute('data-target'));
            let count = 0;
            const duration = 2000;
            const increment = target / (duration / 16);
            const counter = setInterval(() => {
              count += increment;
              if (count >= target) {
                entry.target.innerText = target;
                clearInterval(counter);
              } else {
                entry.target.innerText = Math.floor(count);
              }
            }, 16);
            entry.target.classList.remove('animated-counter'); // Run once
          }
        }
      });
    }, observerOptions);

    const animatedElements = document.querySelectorAll(
      '.scroll-fade-up, .scroll-fade-left, .scroll-fade-right, .scroll-blur-in, .scroll-rotate-in, .animated-come-from, .animated-counter'
    );
    animatedElements.forEach(el => observer.observe(el));

    // Hover Glow Tracker
    const glowElements = document.querySelectorAll('.hover-glow');
    glowElements.forEach(el => {
      const handleMouseMove = (e) => {
        const rect = el.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        el.style.setProperty('--mouse-x', `${x}px`);
        el.style.setProperty('--mouse-y', `${y}px`);
      };
      el.addEventListener('mousemove', handleMouseMove);
      
      // Cleanup for hover listener
      el._cleanupHover = () => el.removeEventListener('mousemove', handleMouseMove);
    });

    return () => {
      animatedElements.forEach(el => observer.unobserve(el));
      glowElements.forEach(el => {
        if (el._cleanupHover) el._cleanupHover();
      });
    };
  }, []);
}
