"use client";
import React, { useEffect, useState } from 'react';
import { useAnimations } from './hooks/useAnimations';

export default function Profile() {
  useAnimations();
  const [githubRepos, setGithubRepos] = useState(4);
  const [leetcodeProblems, setLeetcodeProblems] = useState(63);

  useEffect(() => {
    fetch('/api/activity/github')
      .then(res => res.json())
      .then(data => {
        if (data.success && data.data?.profile?.public_repos) {
          setGithubRepos(data.data.profile.public_repos);
        }
      })
      .catch(console.error);

    fetch('/api/activity/leetcode')
      .then(res => res.json())
      .then(data => {
        if (data.success && data.data?.stats?.All) {
          setLeetcodeProblems(data.data.stats.All);
        }
      })
      .catch(console.error);
  }, []);

  return (
    <section id="about" className="bento-card col-span-8">
      <div className="split-layout">
        <div className="split-left scroll-fade-right">
          <h2 className="section-title mb-8">ABOUT</h2>
          <h2 className="massive-text gradient-amber scroll-blur-in" style={{ fontSize: 'clamp(2rem, 4.5vw, 5rem)', lineHeight: '1', whiteSpace: 'nowrap' }}>
            RAJ<br />MAHESHWARI.
          </h2>
        </div>
        <div className="split-right scroll-fade-left pt-6">
          <p className="editorial-text mb-6">
            AI/ML Engineering student at GLA University, Mathura. I build intelligent software systems — from data pipelines and ML models to full-stack web applications.
          </p>
          <p className="editorial-text-small text-muted mb-8">
            My work sits at the intersection of machine learning, backend engineering, and data analysis. I don't just train models — I build the architecture that serves them. Currently focused on deep learning, NLP, and scalable Python backends.
          </p>
          
          {/* Quick Stats Bento */}
          <div className="about-bento scroll-fade-up">
            <div className="about-bento-item hover-glow glow-amber">
              <span className="about-bento-num animated-counter" id="about-lc-count" data-target={leetcodeProblems}>{leetcodeProblems}</span>
              <span className="about-bento-label">LEETCODE<br />PROBLEMS</span>
            </div>
            <div className="about-bento-item hover-glow glow-amber">
              <span className="about-bento-num animated-counter" data-target={githubRepos}>{githubRepos}</span>
              <span className="about-bento-label">GITHUB<br />REPOSITORIES</span>
            </div>
            <div className="about-bento-item hover-glow glow-amber">
              <span className="about-bento-num"><span className="animated-counter" data-target="5">5</span>+</span>
              <span className="about-bento-label">LANGUAGES<br />PROFICIENT</span>
            </div>
            <div className="about-bento-item hover-glow glow-amber">
              <span className="about-bento-num" style={{ fontSize: '2rem' }}>AZ-900</span>
              <span className="about-bento-label">MICROSOFT<br />CERTIFIED</span>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
