"use client";
import './MatrixRain.css'

const CHARS = '01ABCDEFXYZ$#%&SDGKUHRQMTJY'

// Deterministic pseudo-random glyphs so layout is stable across renders.
function buildGlyphs(count) {
  let seed = 42
  const rand = () => {
    seed = (seed * 9301 + 49297) % 233280
    return seed / 233280
  }
  return Array.from({ length: count }, (_, i) => ({
    char: CHARS[Math.floor(rand() * CHARS.length)],
    left: (rand() * 100).toFixed(1),
    top: (rand() * 100).toFixed(1),
    size: 11 + Math.floor(rand() * 9),
    opacity: (0.08 + rand() * 0.22).toFixed(2),
    delay: (rand() * 6).toFixed(2),
    tone: i % 3 === 0 ? 'red' : 'blue',
  }))
}

const GLYPHS = buildGlyphs(34)

export default function MatrixRain() {
  return (
    <div className="matrix-rain" aria-hidden="true">
      {GLYPHS.map((g, i) => (
        <span
          key={i}
          className={`matrix-rain__glyph matrix-rain__glyph--${g.tone}`}
          style={{
            left: `${g.left}%`,
            top: `${g.top}%`,
            fontSize: `${g.size}px`,
            opacity: g.opacity,
            animationDelay: `${g.delay}s`,
          }}
        >
          {g.char}
        </span>
      ))}
    </div>
  )
}
