"use client";
import React, { useEffect, useState } from 'react';
import { useAnimations } from './hooks/useAnimations';

export default function Activity() {
  useAnimations();

  const [github, setGithub] = useState(null);
  const [leetcode, setLeetcode] = useState(null);
  
  // Terminal Chat State
  const [chatInput, setChatInput] = useState('');
  const [isChatLoading, setIsChatLoading] = useState(false);
  const [chatLog, setChatLog] = useState([
    { type: 'system', text: '[SYSTEM ONLINE] Initialization complete.' },
    { type: 'system', text: "Type 'help' or ask a question about Raj." }
  ]);

  const handleChatSubmit = async () => {
    const input = chatInput.trim();
    if (!input) return;

    setChatLog(prev => [...prev, { type: 'user', text: input }]);
    setChatInput('');
    setIsChatLoading(true);

    try {
      const res = await fetch('/api/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ messages: [{ role: 'user', content: input }] })
      });
      const data = await res.json();
      setChatLog(prev => [...prev, { type: 'system', text: data.reply }]);
    } catch (err) {
      setChatLog(prev => [...prev, { type: 'system', text: 'Error connecting to AI backend.', isError: true }]);
    } finally {
      setIsChatLoading(false);
      
      // Auto-scroll terminal
      setTimeout(() => {
        const tb = document.getElementById('terminal-body');
        if (tb) tb.scrollTop = tb.scrollHeight;
      }, 50);
    }
  };

  useEffect(() => {
    fetch('/api/activity/github')
      .then(res => res.json())
      .then(data => {
        if (data.success) setGithub(data.data);
      })
      .catch(console.error);

    fetch('/api/activity/leetcode')
      .then(res => res.json())
      .then(data => {
        if (data.success) setLeetcode(data.data);
      })
      .catch(console.error);
  }, []);

  return (
    <>
      {/* Chapter 7: Inside the Machine */}
      <section id="machine" className="bento-card col-span-12 text-center">
        <h2 className="massive-text scroll-scale">INSIDE</h2>
        <h2 className="massive-text text-outline scroll-scale delay-1">THE MACHINE.</h2>
        <p className="lead-text mt-8 mb-20 scroll-fade-up delay-2">Exploring the systems behind intelligent software.</p>
        
        <div className="nn-interactive scroll-fade-up delay-3">
          <div className="nn-col">
            <span className="nn-label">INPUT</span>
            <div className="node-circle" data-info="Feature X1"></div>
            <div className="node-circle" data-info="Feature X2"></div>
            <div className="node-circle" data-info="Feature X3"></div>
          </div>
          <div className="nn-col">
            <span className="nn-label">HIDDEN</span>
            <div className="node-circle" data-info="Weight: 0.85"></div>
            <div className="node-circle" data-info="Weight: -0.12"></div>
            <div className="node-circle" data-info="Weight: 0.99"></div>
            <div className="node-circle" data-info="Weight: 0.43"></div>
          </div>
          <div className="nn-col">
            <span className="nn-label">HIDDEN</span>
            <div className="node-circle" data-info="Activation: ReLU"></div>
            <div className="node-circle" data-info="Activation: ReLU"></div>
            <div className="node-circle" data-info="Activation: ReLU"></div>
            <div className="node-circle" data-info="Activation: ReLU"></div>
          </div>
          <div className="nn-col">
            <span className="nn-label">OUTPUT</span>
            <div className="node-circle" data-info="Prediction: 0.95"></div>
            <div className="node-circle" data-info="Prediction: 0.05"></div>
          </div>
        </div>
        <div id="nn-tooltip" className="nn-tooltip">DATA</div>

        {/* Interactive System Terminal */}
        <div className="interactive-terminal mt-32 mx-auto max-w-md scroll-fade-up delay-4">
          <div className="terminal-header">
            <div className="term-dots">
              <span className="dot close"></span>
              <span className="dot min"></span>
              <span className="dot max"></span>
            </div>
            <div className="term-title">raj@system: ~</div>
          </div>
          <div className="terminal-body" id="terminal-body" style={{ maxHeight: '300px', overflowY: 'auto' }}>
            {chatLog.map((log, i) => (
              <div key={i} className={`term-line ${log.type === 'user' ? 'input' : 'output'}`}>
                {log.type === 'user' ? (
                  <><span className="term-prompt">raj@system:~$</span> {log.text}</>
                ) : (
                  <>{log.isError ? <span style={{color: 'red'}}>{log.text}</span> : <>{log.text}</>}</>
                )}
              </div>
            ))}
            {isChatLoading && <div className="term-line output"><span className="term-highlight">Processing query...</span></div>}
          </div>
          <div className="terminal-input-wrapper">
            <span className="term-prompt">raj@system:~$</span>
            <input 
              type="text" 
              className="terminal-input" 
              placeholder={isChatLoading ? "Waiting for AI..." : "Type 'help' or ask a question..."}
              autoComplete="off" 
              spellCheck="false"
              value={chatInput}
              onChange={(e) => setChatInput(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && chatInput.trim() && !isChatLoading) {
                  handleChatSubmit();
                }
              }}
              disabled={isChatLoading}
            />
          </div>
        </div>
        
        <div className="mt-32">
          <h2 className="massive-text scroll-slide-up">DATA <span className="text-outline">BECOMES SIGNAL.</span></h2>
          <h2 className="massive-text scroll-slide-up mt-8">SIGNAL <span className="text-outline">BECOMES A MODEL.</span></h2>
          <h2 className="massive-text scroll-slide-up mt-8">A MODEL <span className="text-outline">BECOMES A PREDICTION.</span></h2>
        </div>
      </section>

      {/* Chapter 8: Developer Signal */}
      <section id="activity" className="bento-card col-span-12">
        <h2 className="massive-text scroll-slide-up">WHAT I</h2>
        <h2 className="massive-text scroll-slide-up delay-1">ACTUALLY DO.</h2>
        <p className="editorial-text-small text-muted mt-6 mb-20 scroll-fade-up">
          Projects show what I build. GitHub shows what I code. LeetCode shows how I solve.
        </p>
        
        {/* GitHub Section */}
        <div className="signal-section scroll-fade-up">
          <div className="signal-header">
            <h2 className="section-title">GITHUB <span className="live-badge">â— LIVE API</span></h2>
            <a href="https://github.com/rajmaheshwari3001-dev" target="_blank" rel="noopener noreferrer" className="view-btn">VIEW PROFILE</a>
          </div>
          
          <div className="gh-advanced-grid mt-12">
            <div className="gh-col">
              <div className="gh-profile-card hover-glow">
                <img id="gh-avatar" src={github?.profile?.avatar_url || "https://avatars.githubusercontent.com/u/1?v=4"} alt="GitHub" className="gh-avatar" />
                <div className="gh-info">
                  <h3 id="gh-name" className="gh-name">{github?.profile?.login || "Loading..."}</h3>
                  <div className="gh-metrics">
                    <span><span id="gh-repos" className="num">{github?.profile?.public_repos || "--"}</span> REPOS</span>
                    <span><span id="gh-followers" className="num">{github?.profile?.followers || "--"}</span> FOLLOWERS</span>
                  </div>
                </div>
              </div>
              
              <div className="gh-langs mt-12">
                <h5 className="sub-label mb-4">LANGUAGE ARCHITECTURE</h5>
                <div id="gh-lang-container" className="led-container">
                  {github?.languages ? Object.entries(github.languages).map(([lang, pct]) => (
                    <div key={lang} className="lang-row">
                      <span className="lang-name">{lang}</span>
                      <div className="led-bar">
                        <div className="led-fill" style={{ width: `${pct}%` }}></div>
                      </div>
                    </div>
                  )) : <div className="text-muted">Loading languages...</div>}
                </div>
              </div>
            </div>
            
            <div className="gh-col">
              <h5 className="sub-label mb-4">DEPLOYED ASSETS</h5>
              <div id="gh-repo-list" className="repo-grid" style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                {github?.repos ? github.repos.map(repo => (
                  <a key={repo.name} href={repo.url} target="_blank" rel="noopener noreferrer" className="repo-card hover-glow glow-blue" style={{ display: 'block', padding: '1.5rem', background: 'var(--surface-glass)', border: '1px solid var(--border-glass)' }}>
                    <div className="flex justify-between items-center mb-2">
                      <h4 style={{ color: 'var(--c-accent-blue)', fontFamily: 'var(--font-heading)', fontWeight: '600' }}>{repo.name}</h4>
                      <span style={{ fontSize: '0.8rem', color: 'var(--c-dark-muted)' }}>â­ {repo.stars}</span>
                    </div>
                    <span style={{ fontSize: '0.8rem', padding: '0.2rem 0.5rem', background: 'rgba(255,255,255,0.05)', borderRadius: '4px' }}>{repo.language}</span>
                  </a>
                )) : <div className="text-muted">Loading repos...</div>}
              </div>
            </div>
          </div>
        </div>
        
        {/* Leetcode Section */}
        <div className="signal-section mt-32 scroll-fade-up">
          <div className="signal-header">
            <h2 className="section-title">HOW I SOLVE (LEETCODE) <span className="live-badge">â— LIVE API</span></h2>
            <a href="https://leetcode.com/rajmaheshwari3001-dev/" target="_blank" rel="noopener noreferrer" className="view-btn">VIEW PROFILE</a>
          </div>
          
          <div className="lc-advanced-grid mt-12">
            <div className="lc-visual-col">
              <div className="neural-rings-container" style={{ position: 'relative', width: '100%', height: '250px', display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
                <div className="ring-center" style={{ position: 'absolute' }}>
                  <span className="ring-label">SOLVED</span>
                  <h2 className="ring-total glitch-text">{leetcode?.stats?.All || "0"}</h2>
                </div>
                {/* SVG Circle representing solved percentage */}
                <svg width="200" height="200" style={{ transform: 'rotate(-90deg)' }}>
                  <circle cx="100" cy="100" r="90" fill="none" stroke="rgba(255,255,255,0.05)" strokeWidth="8" />
                  <circle cx="100" cy="100" r="90" fill="none" stroke="var(--c-accent-blue)" strokeWidth="8" strokeDasharray="565" strokeDashoffset={565 - (565 * (leetcode ? Math.min(leetcode.stats.All / 100, 1) : 0))} style={{ transition: 'stroke-dashoffset 1.5s ease-out' }} />
                </svg>
              </div>
            </div>
            
            <div className="lc-stats-col">
              <div className="lc-stat-box hover-glow glow-emerald box-easy">
                <span className="stat-glow"></span>
                <div className="stat-header">EASY</div>
                <div className="stat-val glitch-text">{leetcode?.stats?.Easy || "0"}</div>
              </div>
              <div className="lc-stat-box hover-glow glow-amber box-med">
                <span className="stat-glow"></span>
                <div className="stat-header">MEDIUM</div>
                <div className="stat-val glitch-text">{leetcode?.stats?.Medium || "0"}</div>
              </div>
              <div className="lc-stat-box hover-glow glow-rose box-hard">
                <span className="stat-glow"></span>
                <div className="stat-header">HARD</div>
                <div className="stat-val glitch-text">{leetcode?.stats?.Hard || "0"}</div>
              </div>
            </div>
          </div>
        </div>
      </section>
    </>
  );
}

