"use client";
import { Bot, Home, User, Briefcase, Zap, LineChart, Map, Mail } from 'lucide-react'
import { nav, meta } from '../data/content.js'
import './Sidebar.css'

const ICONS = { Home, User, Briefcase, Zap, LineChart, Map, Mail }

export default function Sidebar({ items = nav, logoLabel = meta.logoLabel }) {
  return (
    <aside className="sidebar" aria-label="Primary navigation">
      <div className="sidebar__logo" role="img" aria-label={`${logoLabel} logo`}>
        <Bot size={22} strokeWidth={2} />
      </div>

      <nav className="sidebar__nav">
        <ul>
          {items.map((item) => {
            const Icon = ICONS[item.icon] ?? Home
            return (
              <li key={item.id}>
                <button
                  type="button"
                  className={`sidebar__link${item.active ? ' sidebar__link--active' : ''}`}
                  aria-current={item.active ? 'page' : undefined}
                  title={item.label}
                >
                  <Icon size={19} strokeWidth={2} />
                  <span className="sidebar__link-label">{item.label}</span>
                </button>
              </li>
            )
          })}
        </ul>
      </nav>

      <div className="sidebar__rail" aria-hidden="true" />
    </aside>
  )
}
