"use client";
import { statusPanel } from '../data/content.js'
import StatusPill from './StatusPill.jsx'
import './StatusPanel.css'

export default function StatusPanel({ items = statusPanel }) {
  return (
    <aside className="status-panel" aria-label="System status">
      {items.map((item) => (
        <StatusPill key={item.label} {...item} />
      ))}
    </aside>
  )
}
