"use client";
import './BackgroundEffects.css'

// Deterministic star positions so the field doesn't reshuffle on re-render.
const STARS = Array.from({ length: 46 }, (_, i) => {
  const seed = i * 137.5
  return {
    left: (seed % 100).toFixed(2),
    top: ((seed * 1.618) % 100).toFixed(2),
    size: 1 + (i % 3),
    delay: (i % 7) * 0.6,
  }
})

function WaveThreads({ className }) {
  return (
    <svg
      className={className}
      viewBox="0 0 900 700"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      preserveAspectRatio="xMidYMid slice"
      aria-hidden="true"
    >
      <defs>
        <linearGradient id="thread-grad" x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stopColor="var(--red-500)" stopOpacity="0.85" />
          <stop offset="55%" stopColor="var(--blue-500)" stopOpacity="0.55" />
          <stop offset="100%" stopColor="var(--blue-500)" stopOpacity="0" />
        </linearGradient>
      </defs>

      <g stroke="url(#thread-grad)" strokeWidth="1.1" opacity="0.55">
        <path d="M -40 260 C 180 180, 340 340, 520 200 S 860 120, 940 40" />
        <path d="M -40 340 C 200 260, 360 420, 560 280 S 880 200, 980 120" />
        <path d="M -40 180 C 160 120, 300 260, 480 140 S 820 40, 960 -20" />
        <path d="M -60 420 C 140 360, 320 500, 500 380 S 840 300, 960 240" />
      </g>

      <g stroke="url(#thread-grad)" strokeWidth="0.6" opacity="0.3">
        {Array.from({ length: 22 }).map((_, i) => (
          <circle
            key={i}
            cx={(i * 41) % 900}
            cy={(i * 67) % 700}
            r="1.4"
            fill="var(--blue-400)"
            stroke="none"
          />
        ))}
      </g>
    </svg>
  )
}

export default function BackgroundEffects() {
  return (
    <div className="bg-fx" aria-hidden="true">
      <div className="bg-fx__grid" />

      <WaveThreads className="bg-fx__waves bg-fx__waves--tr" />
      <WaveThreads className="bg-fx__waves bg-fx__waves--bl" />

      <div className="bg-fx__stars">
        {STARS.map((s, i) => (
          <span
            key={i}
            className="bg-fx__star"
            style={{
              left: `${s.left}%`,
              top: `${s.top}%`,
              width: s.size,
              height: s.size,
              animationDelay: `${s.delay}s`,
            }}
          />
        ))}
      </div>

      <div className="bg-fx__vignette" />
    </div>
  )
}
