"use client";
import { hero } from '../data/content.js'
import MatrixRain from './MatrixRain.jsx'
import StatusPill from './StatusPill.jsx'
import './Hero.css'

export default function Hero({ data = hero }) {
  return (
    <section className="hero" aria-label="Introduction">
      <div className="hero__headline-wrap">
        <MatrixRain />
        <h1 className="hero__headline">
          {data.headlineLines.map((line, i) => (
            <span className="hero__headline-line" key={i}>
              {line}
            </span>
          ))}
        </h1>
      </div>

      <div className="hero__byline">
        <p className="hero__name">{data.name}</p>
        <p className="hero__role">{data.role}</p>
      </div>

      <p className="hero__bio">{data.bio}</p>

      <div className="hero__pills">
        {data.pills.map((p) => (
          <StatusPill key={p.label} {...p} />
        ))}
      </div>
    </section>
  )
}
