"use client";
import './GlowOrb.css'

export default function GlowOrb() {
  return (
    <div className="glow-orb" aria-hidden="true">
      <div className="glow-orb__halo" />

      <svg
        className="glow-orb__mandala"
        viewBox="0 0 360 360"
        xmlns="http://www.w3.org/2000/svg"
      >
        <defs>
          <radialGradient id="orb-core" cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor="#fff" stopOpacity="0.95" />
            <stop offset="35%" stopColor="var(--red-400)" stopOpacity="0.8" />
            <stop offset="100%" stopColor="var(--red-500)" stopOpacity="0" />
          </radialGradient>
          <filter id="orb-blur" x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur stdDeviation="4" />
          </filter>
        </defs>

        <g className="glow-orb__ring glow-orb__ring--slow" stroke="var(--blue-400)" fill="none" opacity="0.55">
          {Array.from({ length: 6 }).map((_, i) => {
            const angle = (i * 60 * Math.PI) / 180
            const cx = 180 + 62 * Math.cos(angle)
            const cy = 180 + 62 * Math.sin(angle)
            return <circle key={i} cx={cx} cy={cy} r="62" strokeWidth="1" />
          })}
        </g>

        <g className="glow-orb__ring glow-orb__ring--fast" stroke="var(--red-400)" fill="none" opacity="0.45">
          <circle cx="180" cy="180" r="120" strokeWidth="0.8" strokeDasharray="2 10" />
        </g>

        <circle cx="180" cy="180" r="46" fill="url(#orb-core)" filter="url(#orb-blur)" />
      </svg>

      <div className="glow-orb__particles">
        {Array.from({ length: 12 }).map((_, i) => (
          <span
            key={i}
            className="glow-orb__particle"
            style={{
              transform: `rotate(${i * 30}deg) translateX(150px)`,
              animationDelay: `${i * 0.25}s`,
            }}
          />
        ))}
      </div>
    </div>
  )
}
