"use client";
import './StatusPill.css'

export default function StatusPill({ label, value, tone = 'blue', pulse = false }) {
  return (
    <div className={`status-pill status-pill--${tone}`}>
      <span className="status-pill__label">{label}:</span>
      <span className="status-pill__value">
        {pulse && <span className="status-pill__dot" aria-hidden="true" />}
        {value}
      </span>
    </div>
  )
}
